            return "ca" + s[2:]
        return None

    def rule6(s: str) -> str | None:
        idx = s.find('ca', 1)
        if idx != -1:
            return s[:idx] + s[idx+2:]
        return None

    def rule7(s: str) -> str | None:
        if s.endswith('bb'):
            return s[:-2]
        return None

    def rule8(s: str) -> str | None:
        if s.startswith('ac'):
            return "zz" + s[2:]
        return None

    rules = [rule1, rule2, rule3, rule4, rule5, rule6, rule7, rule8]
