def solve():
    from typing import Callable, List
    def apply_string_rules(s: str, rules: List[Callable[[str], str | None]]) -> str:
        seen: set[str] = set()
        while True:
            applied = False
            for rule in rules:
                new_s = rule(s)
                if new_s is not None:
                    if new_s == s or new_s in seen:
                        return s
                    seen.add(s)
                    s = new_s
                    applied = True
                    break
            if not applied:
                return s

    def rule1(s: str) -> str | None:
        if 'acb' in s:
            return s.replace('acb', 'bca', 1)
        return None

    def rule2(s: str) -> str | None:
        if len(s) > 15:
            mid = len(s) // 2
            return s[:mid] + s[mid + 1:]
        return None

    def rule3(s: str) -> str | None:
        if s.startswith('ac'):
            return 'zz' + s[2:]
        return None

    def rule4(s: str) -> str | None:
        if s.endswith('ba'):
            return s[:-2] + 'ab'
        return None

    def rule5(s: str) -> str | None:
        if s.startswith('cc'):
            return s[2:]
        return None

    def rule6(s: str) -> str | None:
        if s.endswith('ac'):
            return s[:-2] + 'cb'
        return None

    def rule7(s: str) -> str | None:
        if s.startswith('ca'):
            return 'bb' + s[2:] + 'c'
        return None

    def rule8(s: str) -> str | None:
        if s.startswith('cb'):
            new = 'aa' + s[2:]
            # delete the last character of the resulting string
            return new[:-1] if new else ''
        return None

    rules = [rule1, rule2, rule3, rule4, rule5, rule6, rule7, rule8]
    start = "cccaababaaacaaaccb"
    result = apply_string_rules(start, rules)
    return result

